	"smartprocurex/view/SupplierList.view.xml":'<mvc:View\n    controllerName="smartprocurex.controller.SupplierList"\n    xmlns:mvc="sap.ui.core.mvc"\n    xmlns="sap.m"><Page title="Suppliers"\n          showNavButton="true"\n          navButtonPress=".onNavBack"><content><Panel class="sapUiMediumMarginTop sapUiMediumMarginBeginEnd"><headerToolbar><Toolbar><Title text="Supplier Directory"/><ToolbarSpacer/></Toolbar></headerToolbar><Table\n                    id="supplierTable"\n                    items="{supplierModel>/Suppliers}"\n                    sticky="ColumnHeaders"\n                    alternateRowColors="true"><columns><Column><Text text="Supplier Code"/></Column><Column><Text text="Supplier Name"/></Column><Column><Text text="Email"/></Column><Column><Text text="Phone"/></Column><Column hAlign="Center"><Text text="Status"/></Column></columns><items><ColumnListItem\n                            type="Navigation"\n                            press=".onSupplierPress"><cells><Text text="{supplierModel>supplierCode}" class="sapMObjectNumberText"/><Text text="{supplierModel>supplierName}"/><Text text="{supplierModel>email}"/><Text text="{supplierModel>phone}"/><ObjectStatus\n                                    text="{supplierModel>status}"\n                                    state="{\n                                        path:\'supplierModel>status\',\n                                        formatter: \'.getSupplierStatusState\'\n                                    }"/></cells></ColumnListItem></items></Table></Panel></content></Page></mvc:View>\n'
